#!/usr/bin/env bash
# install-status-pipeline.sh: puts the Pipeline page on status.auditisa.com. For the owner to run, on the
# production VPS. GENERATED by deploy/status/build-installer.py: change gen-pipeline.js and rebuild.
#
#   bash install-status-pipeline.sh check                 what would change; changes nothing (the default)
#   bash install-status-pipeline.sh install               backs up, installs, checks, and undoes itself on failure
#   bash install-status-pipeline.sh rollback              back to the page as it was
#   bash install-status-pipeline.sh deploy-key            makes a read-only key for the Odoo repository and prints its PUBLIC half
#
# What it changes, and nothing else:
#   /opt/ea-audit-status/gen-pipeline.js                  new; reads GitHub and the page gen-status.js writes
#   /opt/ea-audit-status/pipeline/                        new; its mirrors and its last reading
#   /etc/systemd/system/ea-audit-status.service.d/pipeline.conf   new; runs it after gen-status.js
#   /etc/systemd/system/ea-audit-status.timer.d/pipeline.conf     new; the timer fires on the minute, within 5 s
#   /var/www/status.auditisa.com/{details.html,en.html,pipeline.json}   new; index.html becomes the new page
#
# gen-status.js, the Next.js services, Apache, DNS and every database are not touched. A failure of the new
# script leaves the old page in place. Backup: /root/status-pipeline-backup-<stamp>.tar.gz, root only.

set -euo pipefail
umask 022

: "${STATUS_PREFIX:=}"
ROOT=$STATUS_PREFIX/opt/ea-audit-status
WWW=$STATUS_PREFIX/var/www/status.auditisa.com
UNITS=$STATUS_PREFIX/etc/systemd/system
BACKUPS=$STATUS_PREFIX/root
KEY=$STATUS_PREFIX/root/.ssh/auditisa_odoo_status_ro
SERVICE=ea-audit-status.service
TIMER=ea-audit-status.timer
GEN=$ROOT/gen-pipeline.js
MARKER='<!-- ea-pipeline-page -->'

log() { printf '[status-pipeline] %s\n' "$*"; }
die() { printf '[status-pipeline] ERROR: %s\n' "$*" >&2; exit 1; }

COMMAND=${1:-check}

need_root() {
  if [ -z "$STATUS_PREFIX" ] && [ "$(id -u)" != 0 ]; then die "run as root"; fi
}

preflight() {
  [ -f "$ROOT/gen-status.js" ] || die "$ROOT/gen-status.js is missing: is this the production VPS?"
  [ -d "$WWW" ] || die "$WWW is missing"
  command -v node >/dev/null || die "node is missing"
  command -v git >/dev/null || die "git is missing"
  command -v curl >/dev/null || die "curl is missing"
}

write_generator() {
  local tmp digest
  tmp=$(mktemp "$GEN.XXXXXX")
  base64 -d > "$tmp" <<'GENERATOR_B64'
@@GENERATOR_B64@@
GENERATOR_B64
  digest=$(sha256sum "$tmp" | cut -d' ' -f1)
  [ "$digest" = "@@GENERATOR_SHA256@@" ] || { rm -f "$tmp"; die "the generator inside this script is damaged"; }
  chmod 755 "$tmp"
  mv -f "$tmp" "$GEN"
}

backup() {
  local stamp file list=()
  stamp=$(date -u +%Y%m%dT%H%M%SZ)
  file=$BACKUPS/status-pipeline-backup-$stamp.tar.gz
  mkdir -p "$BACKUPS"
  for path in "$ROOT" "$WWW" "$UNITS/$SERVICE" "$UNITS/$TIMER" "$UNITS/$SERVICE.d" "$UNITS/$TIMER.d"; do
    if [ -e "$path" ]; then list+=("$path"); fi
  done
  tar --exclude='*.git' -czf "$file" "${list[@]}" 2>/dev/null
  chmod 600 "$file"
  tar -tzf "$file" >/dev/null
  log "backup: $file"
}

remove_all() {
  rm -f "$UNITS/$SERVICE.d/pipeline.conf" "$UNITS/$TIMER.d/pipeline.conf"
  rmdir "$UNITS/$SERVICE.d" "$UNITS/$TIMER.d" 2>/dev/null || true
  rm -f "$GEN" "$WWW/en.html" "$WWW/details.html" "$WWW/pipeline.json"
  rm -rf "$ROOT/pipeline"
  systemctl daemon-reload || log "WARNING: systemctl daemon-reload failed"
  systemctl restart "$TIMER" || log "WARNING: the timer did not restart"
  systemctl start "$SERVICE" || true
}

undo_on_failure() {
  local rc=$?
  trap - EXIT
  if [ "$rc" != 0 ]; then
    log "stopped half way: undoing"
    remove_all
  fi
  exit "$rc"
}

case "$COMMAND" in
  check)
    preflight
    log "nothing is changed by this command"
    log "would add: $GEN; drop-ins in $UNITS/$SERVICE.d and $UNITS/$TIMER.d"
    log "would add: en.html, details.html, pipeline.json in $WWW; index.html becomes the new page"
    if [ -e "$GEN" ]; then log "already installed: install would replace the generator"; fi
    if [ -e "$KEY" ]; then log "read-only key for the Odoo repository: present"; else log "read-only key for the Odoo repository: absent; the Odoo column says so until you run deploy-key"; fi
    ;;
  install)
    need_root
    preflight
    backup
    trap undo_on_failure EXIT
    write_generator
    mkdir -p "$UNITS/$SERVICE.d" "$UNITS/$TIMER.d" "$ROOT/pipeline"
    chmod 700 "$ROOT/pipeline"
    NODE=$(command -v node)
    cat > "$UNITS/$SERVICE.d/pipeline.conf" <<EOF
[Service]
# The leading - : a failure here leaves the old page and does not fail the service.
ExecStartPost=-$NODE $GEN
EOF
    cat > "$UNITS/$TIMER.d/pipeline.conf" <<EOF
[Timer]
AccuracySec=5s
EOF
    systemctl daemon-reload
    systemctl restart "$TIMER"
    systemctl start "$SERVICE" || true
    if ! grep -qF "$MARKER" "$WWW/index.html" || [ ! -s "$WWW/details.html" ] || [ ! -s "$WWW/en.html" ]; then
      die "the new page did not appear: not installed; the page goes back as it was"
    fi
    if grep -qiE 'password|secret|BEGIN [A-Z ]*PRIVATE' "$WWW/index.html" "$WWW/en.html" "$WWW/pipeline.json"; then
      die "the new page holds a word it must not hold: not installed; the page goes back as it was"
    fi
    log "installed. Open https://status.auditisa.com/ and https://status.auditisa.com/details.html"
    log "to go back: bash $0 rollback"
    ;;
  rollback)
    need_root
    remove_all
    if grep -qF "$MARKER" "$WWW/index.html" 2>/dev/null; then
      log "index.html is rewritten by gen-status.js at its next run, within a minute"
    fi
    log "rolled back; the backups stay in $BACKUPS"
    ;;
  deploy-key)
    need_root
    mkdir -p "$(dirname "$KEY")"
    if [ -e "$KEY" ]; then
      log "a key exists already"
    else
      ssh-keygen -q -t ed25519 -N '' -C 'status.auditisa.com read-only' -f "$KEY"
      chmod 600 "$KEY"
    fi
    log "PUBLIC half. Add it as a read-only deploy key of Nekoutb/auditisa-odoo (do NOT tick write access):"
    cat "$KEY.pub"
    log "on your computer, with this line in a file key.pub:"
    log "  gh repo deploy-key add key.pub --repo Nekoutb/auditisa-odoo --title status.auditisa.com-read-only"
    ;;
  *)
    sed -n '2,9p' "$0"
    exit 64 ;;
esac
